implementation:
ACPI_STATUS AcpiPsCompleteThisOp(ACPI_WALK_STATE *WalkState, ACPI_PARSE_OBJECT *Op, ACPI_STATUS Status) {
    ACPI_STATUS Status2 = AE_OK;

    if (!WalkState || !Op) {
        return AE_BAD_PARAMETER;
    }

    if (WalkState->ScopeDepth <= 0) {
        return AE_BAD_PARAMETER;
    }

    if (Status != AE_OK) {
        return Status;
    }

    if (Op->Asl.Value.ArgList) {
        AcpiUtDeleteObjectList(Op->Asl.Value.ArgList);
        Op->Asl.Value.ArgList = NULL;
    }

    if (WalkState->Control.Method)
    {
        if (WalkState->Control.Method->Params && WalkState->Control.ParamCount > 0)
        {
            if (WalkState->Control.ParamCount > Op->Asl.Value.ArgCount)
            {
                return AE_AML_PARAMETERS;
            }
        }
    }

    if (WalkState->ScopeDepth > 0) {
        WalkState->ScopeDepth--;
    }

    return Status2;
}
